pragma solidity ^0.8.16;

import '../structs/JBBitmapWord.sol';

/**
  @notice
  Utilities to manage bool bitmap storing the inactive tiers.
*/
library JBBitmap {
  /**
    @notice
    initialise a BitmapWord struct, based on the mapping storage pointer and a given index.
  */
  function readId(mapping(uint256 => uint256) storage self, uint256 _index)
    internal
    view
    returns (JBBitmapWord memory)
  {
    uint256 _depth = _retrieveDepth(_index);

    return JBBitmapWord({currentWord: self[_depth], currentDepth: _depth});
  }

  /**
    @notice
    Returns the status of a given bit, in the single word stored in a BitmapWord struct.
  */
  function isTierIdRemoved(JBBitmapWord memory self, uint256 _index) internal pure returns (bool) {
    return (self.currentWord >> (_index % 256)) & 1 == 1;
  }

  /**
    @notice
    Returns the status of a bit in a given bitmap (index is the index in the reshaped bitmap matrix 1*n).
  */
  function isTierIdRemoved(mapping(uint256 => uint256) storage self, uint256 _index)
    internal
    view
    returns (bool)
  {
    uint256 _depth = _retrieveDepth(_index);
    return isTierIdRemoved(JBBitmapWord({currentWord: self[_depth], currentDepth: _depth}), _index);
  }

  /**
    @notice
    Flip the bit at a given index to true (this is a one-way operation).
  */
  function removeTier(mapping(uint256 => uint256) storage self, uint256 _index) internal {
    uint256 _depth = _retrieveDepth(_index);
    self[_depth] |= uint256(1 << (_index % 256));
  }

  /**
    @notice
    Return true if the index is in an another word than the one stored in the BitmapWord struct.
  */
  function refreshBitmapNeeded(JBBitmapWord memory self, uint256 _index)
    internal
    pure
    returns (bool)
  {
    return _retrieveDepth(_index) != self.currentDepth;
  }

  // Lib internal

  /**
    @notice
    Return the lines of the bitmap matrix where an index lies.
  */
  function _retrieveDepth(uint256 _index) internal pure returns (uint256) {
    return _index / 256;
  }
}
"},"contracts/libraries/JBIpfsDecoder.sol":{"content":"// SPDX-License-Identifier: MIT
pragma solidity ^0.8.16;

/**
  @notice
  Utilities to decode an IPFS hash.
*/
library JBIpfsDecoder {
  //*********************************************************************//
  // ------------------- internal constant properties ------------------ //
  //*********************************************************************//

  /**
    @notice
    Just a kind reminder to our readers

    @dev
    Used in base58ToString
  */
  bytes internal constant _ALPHABET = '123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz';

  function decode(string memory _baseUri, bytes32 _hexString)
    external
    pure
    returns (string memory)
  {
    // Concatenate the hex string with the fixed IPFS hash part (0x12 and 0x20)
    bytes memory completeHexString = abi.encodePacked(bytes2(0x1220), _hexString);

    // Convert the hex string to an hash
    string memory ipfsHash = _toBase58(completeHexString);

    // Concatenate with the base URI
    return string(abi.encodePacked(_baseUri, ipfsHash));
  }

  /**
    @notice
    Convert an hex string to base58

    @notice 
    Written by Martin Ludfall - Licence: MIT
  */
  function _toBase58(bytes memory _source) private pure returns (string memory) {
    if (_source.length == 0) return new string(0);
    uint8[] memory digits = new uint8[](46); // hash size with the prefix
    digits[0] = 0;
    uint8 digitlength = 1;
    for (uint256 i = 0; i < _source.length; ++i) {
      uint256 carry = uint8(_source[i]);
      for (uint256 j = 0; j < digitlength; ++j) {
        carry += uint256(digits[j]) * 256;
        digits[j] = uint8(carry % 58);
        carry = carry / 58;
      }

      while (carry > 0) {
        digits[digitlength] = uint8(carry % 58);
        digitlength++;
        carry = carry / 58;
      }
    }
    return string(_toAlphabet(_reverse(_truncate(digits, digitlength))));
  }

  function _truncate(uint8[] memory _array, uint8 _length) private pure returns (uint8[] memory) {
    uint8[] memory output = new uint8[](_length);
    for (uint256 i = 0; i < _length; i++) {
      output[i] = _array[i];
    }
    return output;
  }

  function _reverse(uint8[] memory _input) private pure returns (uint8[] memory) {
    uint8[] memory output = new uint8[](_input.length);
    for (uint256 i = 0; i < _input.length; i++) {
      output[i] = _input[_input.length - 1 - i];
    }
    return output;
  }

  function _toAlphabet(uint8[] memory _indices) private pure returns (bytes memory) {
    bytes memory output = new bytes(_indices.length);
    for (uint256 i = 0; i < _indices.length; i++) {
      output[i] = _ALPHABET[_indices[i]];
    }
    return output;
  }
}
